"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1227],{2019(e){e.exports=JSON.parse('{"title":"\uc65c \uc2a4\ud0c0\ud2b8\uc5c5\uc740 React\ub97c \ud3ec\uae30\ud558\uc9c0 \ubabb\ud560\uae4c","date":"2025-11-12","coverUrl":"/kudzu-based-bench/assets/notion/f8658c69f296bf22.png","html":"<h1 data-notion-block-id=\\"2a2e548d-8a8e-8075-9207-ea6316a265d0\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2a6e548d-8a8e-8003-90d5-ca5ca8dea7f4\\" id=\\"2a6e548d-8a8e-8003-90d5-ca5ca8dea7f4\\">\uc65c \uc2a4\ud0c0\ud2b8\uc5c5\uc740 React\ub97c \ud3ec\uae30\ud558\uc9c0 \ubabb\ud560\uae4c</h2><a href=\\"http://evilmartians.com/chronicles/why-startups-choose-react-and-when-you-should-not\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">http://evilmartians.com/chronicles/why-startups-choose-react-and-when-you-should-not</a><p data-notion-block-id=\\"2a6e548d-8a8e-8034-9f82-e3f9abf1ca5d\\">React\ub97c \ud3ec\uae30\ud558\uace0 \uc2f6\uc5b4\ub3c4 \ud3ec\uae30\ud558\uc9c0 \ubabb\ud558\ub294 \uc774\uc720 \uc911 \ud070 \ud558\ub098\uc778 \\"\ucc44\uc6a9\\"\uacfc \\"\uc0dd\ud0dc\uacc4\\"\uc5d0 \ubc18\ubc15\ud558\ub294 \uae00\uc774\uc790, \uc5b4\ub5bb\uac8c \ubcf4\uba74 \uc5b4\uca54 \uc218\ub3c4 \uc5c6\ub294 \uac83\uc744 \ub300\ubcc0\ud574\uc8fc\ub294 \uae00\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#279e548d-8a8e-80bc-bcfb-ea405e329206\\">React\uc5d0 \uc228\uaca8\uc9c4 \ube44\uc6a9</a>\uc5d0\uc11c\ub3c4 \ub9d0\ud558\ub4ef\uc774, \uadf8\ub9ac\uace0 <a href=\\"https://infrequently.org/2024/11/if-not-react-then-what/\\">React\ub97c \uc120\ud0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74</a>\uc5d0\uc11c\ub3c4 \ub9d0\ud558\uc9c0\ub9cc, React\uc758 \ud65c\ubc1c\ud55c \uc0dd\ud0dc\uacc4, \uadf8\ub9ac\uace0 \ub113\uc740 \uc778\uc7ac\ud480\uc740 \ub9e4\ub825\uc801\uc774\uc9c0\ub9cc, \uc0dd\uac01\ubcf4\ub2e4 \ub2e4\ub978 \ud328\ub7ec\ub2e4\uc784, \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ucc44\uc6a9\ud558\ub294 \uac83\uc740 \ud070 \ube44\uc6a9\uc774 \ub4e4\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2a7e548d-8a8e-8061-ad33-c5c9a7e01321\\" id=\\"2a7e548d-8a8e-8061-ad33-c5c9a7e01321\\">URL\uc740 \uc0c1\ud0dc\uc774\ub2e4. \uadf8\ub7ec\uba74 \uc5b4\ub5a4 \uac83\uc744 \uc800\uc7a5\ud574\uc57c \ud560\uae4c?</h2><a href=\\"https://alfy.blog/2025/10/31/your-url-is-your-state.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alfy.blog/2025/10/31/your-url-is-your-state.html</a><p data-notion-block-id=\\"2a3e548d-8a8e-80e2-80e5-f988ea8e6307\\">\uc774\uc804 <a href=\\"https://ones-to-watch.ethansup.net/news/post/211e548d-8a8e-8076-80cd-cabfc20df523#212e548d-8a8e-80c2-ab14-f7e5b75aae7f\\">nuqs \uba54\uc778\ud14c\uc774\ub108\uc758 \ube14\ub85c\uadf8 \uae00</a>\uc5d0\uc11c\ub3c4 \ub9d0\ud558\ub4ef\uc774, <a href=\\"https://ones-to-watch.ethansup.net/news/post/7af650fd-5dc1-48cd-8426-bd80375c3a0d#5e6b18a8-b9e0-40e7-9d7e-3e77b6d9f102\\">UI\ub294 \uc0c1\ud0dc\uc758 \ud568\uc218</a>\ub2e4\uc5d0\uc11c\ub3c4 \ub9d0\ud558\ub4ef\uc774, URL\uc740 \uc0c1\ud0dc\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc6b0\ub9ac\uac00 URL\uc5d0 \uc5b4\ub290 \uc0c1\ud0dc\ub97c \uc800\uc7a5\ud558\uace0 \uc800\uc7a5\ud558\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294\uc9c0\ub294 \uc815\ud574\uc9c0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \uc790\uc2e0\uc758 \ub2e4\ub978 \uae00(<a href=\\"https://alfy.blog/2025/10/16/hidden-cost-of-url-design.html\\">\uc88b\uc740 URL \ub514\uc790\uc778</a>)\uacfc \uc5f0\uacb0\uc9c0\uc5b4\uc11c URL\uc5d0 \uc5b4\ub5a4 \uc0c1\ud0dc\uac00 \uc800\uc7a5\ub418\uc5b4\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2a2e548d-8a8e-80d1-8ccc-eadec5880dff\\" id=\\"2a2e548d-8a8e-80d1-8ccc-eadec5880dff\\">source map\uc740 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud560\uae4c</h2><a href=\\"https://www.polarsignals.com/blog/posts/2025/11/04/javascript-source-maps-internals\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.polarsignals.com/blog/posts/2025/11/04/javascript-source-maps-internals</a><p data-notion-block-id=\\"2a3e548d-8a8e-80f4-b5dc-db680e8c2bea\\">\uc778\ud130\ub809\ud2f0\ube0c\ud558\uac8c \ubc88\ub4e4\ub9c1 \uacfc\uc815\uc5d0\uc11c source map\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ub0b4 \ucf54\ub4dc\uc758 source map\uc774 \uc5b4\ub5a4 \uad6c\uc870\ub97c \ub744\uace0 \uc788\ub294\uc9c0 \uad81\uae08\ud558\ub2e4\uba74 <a href=\\"https://evanw.github.io/source-map-visualization/\\">source map visualization</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"2a8e548d-8a8e-803b-b394-fea018094324\\" id=\\"2a8e548d-8a8e-803b-b394-fea018094324\\"><code>\\"use ...\\"</code>\ub85c \uc0dd\uac01\ud558\ub294 Vercel\uc758 \ubbf8\ub798</h2><a href=\\"https://dev.to/herrington_darkholme/the-new-programming-frontier-why-vercel-is-redefining-the-language-2ij0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/herrington_darkholme/the-new-programming-frontier-why-vercel-is-redefining-the-language-2ij0</a><p data-notion-block-id=\\"2a8e548d-8a8e-8056-91b3-cac6e2afcb47\\"><code>\\"use workflow\\"</code>, <code>\\"use cache\\"</code> \ub4f1\uc73c\ub85c JS\uc5d0\uc11c \uc778\ud504\ub77c\ub97c \ucee8\ud2b8\ub864\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\uace0, \uc774\ub294 JS\uc758 \ub2e4\ub978 \ubc29\ud5a5, \ud639\uc740 \ub2e4\ub978 \uc5b8\uc5b4\uc758 \ub4f1\uc7a5\uc744 \uc608\uace0\ud560\uc9c0\ub3c4 \ubaa8\ub978\ub2e4\ub294 \uc0c8\ub85c\uc6b4 \uad00\uc810\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2a3e548d-8a8e-802a-9812-f6907dd0eb69\\" id=\\"2a3e548d-8a8e-802a-9812-f6907dd0eb69\\">PPR(Partial Pre-Rendering)\uc758 \ud604\ud669</h2><a href=\\"https://wyattjoh.ca/blog/partial-prerendering\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wyattjoh.ca/blog/partial-prerendering</a><p data-notion-block-id=\\"2a9e548d-8a8e-8092-bc69-ce8d73b362e0\\">Next.js 14\uc5d0\uc11c \ubc1c\ud45c\ud55c \uc0ac\uc804 \ub80c\ub354\ub9c1\uacfc \ud604\uc7ac(Next.js 16)\uc758 \uc0ac\uc804\ub80c\ub354\ub9c1\uc740 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0, \uc5b4\ub5bb\uac8c \ub098\uc544\uac08 \uac83\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Vercel \uc678\uc758 \ub2e4\ub978 \ud50c\ub7ab\ud3fc\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc9c4\ud589\ub420\uc9c0 \uc9c0\ucf1c\ubd10\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2a2e548d-8a8e-8005-a645-e15b2e3f3e88\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2a3e548d-8a8e-8089-93f6-e9395cd68a4a\\" id=\\"2a3e548d-8a8e-8089-93f6-e9395cd68a4a\\">Three.js\ub85c \uc608\uc220\uc791\ud488 \ub9cc\ub4e4\uae30</h2><a href=\\"https://tympanus.net/codrops/2025/01/15/creating-generative-artwork-with-three-js/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tympanus.net/codrops/2025/01/15/creating-generative-artwork-with-three-js/</a><h2 data-notion-block-id=\\"2a8e548d-8a8e-80fa-b6f3-d30e38ac0ae4\\" id=\\"2a8e548d-8a8e-80fa-b6f3-d30e38ac0ae4\\"><code>NaN !== NaN</code>\uc778 \uc774\uc720(C \uc5d0\ub514\uc158)</h2><a href=\\"https://pzarycki.com/en/posts/js-nan/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pzarycki.com/en/posts/js-nan/</a><h2 data-notion-block-id=\\"2a8e548d-8a8e-80a4-b91f-e5ca703218d7\\" id=\\"2a8e548d-8a8e-80a4-b91f-e5ca703218d7\\">\uc65c \uc6b0\ub9ac\ub294 Form\uc744 \uc0ac\uc6a9\ud560 \ub54c Jotai\ub97c \uc0ac\uc6a9\ud588\ub294\uac00</h2><a href=\\"https://runharbor.com/blog/2025-10-26-improving-deeply-nested-react-render-performance-with-jotai-atomic-state\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://runharbor.com/blog/2025-10-26-improving-deeply-nested-react-render-performance-with-jotai-atomic-state</a><h2 data-notion-block-id=\\"2a9e548d-8a8e-80b7-99a6-d3cec0a9362b\\" id=\\"2a9e548d-8a8e-80b7-99a6-d3cec0a9362b\\">\uc0c9\uc0c1\ub9cc\uc774 \uc815\ubcf4\ub97c \ub098\ud0c0\ub0b8\ub2e4\uba74 \uc811\uadfc\uc131 \uc624\ub958\ub2e4.</h2><a href=\\"https://blog.pope.tech/2025/11/03/grayscale-testing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.pope.tech/2025/11/03/grayscale-testing/</a><h2 data-notion-block-id=\\"2a9e548d-8a8e-806f-8fe5-e0bc0ce3a0f7\\" id=\\"2a9e548d-8a8e-806f-8fe5-e0bc0ce3a0f7\\">Cloudflare Durable Objects\uac00 5\uc0b4\uc774 \uc774\ud574\ud560 \uc218 \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \uc124\uba85\ud574\uc918.</h2><a href=\\"https://boristane.com/blog/what-are-cloudflare-durable-objects/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://boristane.com/blog/what-are-cloudflare-durable-objects/</a><h1 data-notion-block-id=\\"2a2e548d-8a8e-801f-8ca2-f0fa6f9b5a09\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://jfrog.com/blog/CVE-2025-11953-critical-react-native-community-cli-vulnerability/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jfrog.com/blog/CVE-2025-11953-critical-react-native-community-cli-vulnerability/</a><p data-notion-block-id=\\"2a3e548d-8a8e-80df-b592-fd5e63c535b9\\">react native cli\uc5d0 \ubcf4\uc548 \ucde8\uc57d\uc810\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://turborepo.com/blog/turbo-2-6\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://turborepo.com/blog/turbo-2-6</a><p data-notion-block-id=\\"2a3e548d-8a8e-8009-856e-c831c97c7936\\">Bun \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc9c0\uc6d0\ub3c4 \uc8fc\ubaa9\ud560\ub9cc\ud558\uc9c0\ub9cc, Turborepo\uae30\ubc18\uc73c\ub85c MFE\ub97c \uad6c\uc131\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc774 \uac00\uc7a5 \uc778\uc0c1\uae4a\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.reactnativecrossroads.com/posts/introducing-uniwind-the-fastest-tailwind-bindings-for-react-native\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.reactnativecrossroads.com/posts/introducing-uniwind-the-fastest-tailwind-bindings-for-react-native</a><p data-notion-block-id=\\"2a3e548d-8a8e-80b6-ba33-def024ecd98f\\">React Native\uc5d0\uc11c tailwindcss\ubc29\uc2dd\uc73c\ub85c \uc2a4\ud0c0\uc77c\ub9c1\uc744 \ud560 \uc218 \uc788\ub294 Uniwind \uc18c\uac1c\uc785\ub2c8\ub2e4.</p><a href=\\"https://dev.to/analogjs/announcing-analogjs-20-348d\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/analogjs/announcing-analogjs-20-348d</a><p data-notion-block-id=\\"2a8e548d-8a8e-8013-9d9b-e87b38ec915f\\">Angular + Vite \uae30\ubc18 \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc778 AnalogJS\uac00 2\ubc84\uc804\uc774 \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://nodejs.org/en/blog/migrations/v22-to-v24\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/en/blog/migrations/v22-to-v24</a><p data-notion-block-id=\\"2a5e548d-8a8e-8035-8f94-dfcd007f13c6\\">24\ubc84\uc804\uc774 LTS\uac00 \ub418\uba74\uc11c \uc5b4\ub5a4 \uac83\uc774 \ubc14\ub00c\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 codemod\ub85c \ub300\ube44\ud560 \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"2a5e548d-8a8e-80c1-839a-c3d16263d0cd\\"></p>"}')}}]);